<script lang="ts">
 import type {Project} from './model';import {auxiliaryTable,auxiliaryHTML,type AuxiliaryKind} from './auxiliary-reports';import {reportFilterData,emptyReportFilters} from './report-filter-data';import {openReportSettings} from './report-settings';import ReportFilter from './ReportFilter.svelte';import {openInterval} from './report-interval';import {monthLastDay} from './report-dates';import {exportPDF,exportBinary,exportText,native} from './storage';import {tableXLSX} from './xlsx';import {csv} from './engine';import {translator} from './i18n';import {ReceiptText,Settings2,Printer,Download} from '@lucide/svelte';
 export let project:Project;export let kind:AuxiliaryKind;export let title:string;export let initialAccountId="";export let initialPeriod=project.settings.period;
 let from=initialPeriod+'-01',to=monthLastDay(initialPeriod),filters=emptyReportFilters(),generated='',error='',ready=false,frame:HTMLIFrameElement,lastSignature='';let sort:{column:number;descending:boolean}[]=[];
 if(initialAccountId)filters[0]={...filters[0],enabled:true,values:[initialAccountId]};
 $:t=translator(project.settings.language);$:data=reportFilterData(project);$:table=(()=>{try{const result=auxiliaryTable(project,kind,from,to,filters);if(sort.length)result.rows.sort((a,b)=>{for(const rule of sort){const c=(a[rule.column]||'').localeCompare(b[rule.column]||'',project.settings.language,{numeric:true});if(c)return rule.descending?-c:c;}return 0;});return result;}catch{return null;}})();
 $:{const signature=JSON.stringify([from,to,filters,sort,project]);if(signature!==lastSignature){generated='';ready=false;lastSignature=signature;}}
 function configure(){openReportSettings({id:kind,filters,sort,labels:data.labels,items:data.items,columns:table?.headers||[],onapply:(f,s)=>{filters=f;sort=s;}});}
 function generate(){try{if(!table)throw Error(t('Проверьте период и отбор.','Verificați perioada și filtrul.'));generated=auxiliaryHTML(project,title,from,to,table);ready=false;error='';}catch(e){error=String(e);}}
 async function download(format:string){try{if(!table)throw Error(t('Проверьте период.','Verificați perioada.'));const name='OpenHaU-'+kind+'-'+from+'-'+to+'.'+format,html=auxiliaryHTML(project,title,from,to,table);if(format==='pdf')await exportPDF(name,html,true);else if(format==='xlsx')await exportBinary(name,tableXLSX(title,project.organization.name,table.headers,table.rows,table.numericStart,table.numericCount,{totalLastRow:false}),'xlsx');else await exportText(name,format==='csv'?csv([table.headers,...table.rows]):html,format);error='';}catch(e){error=String(e);}}
</script>
<div class="aux-report"><nav><button onclick={generate}><ReceiptText size={16}/>{t('Сформировать','Generează')}</button><button onclick={configure}><Settings2 size={16}/>{t('Настройка…','Configurare…')}</button></nav><div class="period"><span>{t('Период с','Perioada de la')}</span><input type="date" bind:value={from}/><span>{t('по','până la')}</span><input type="date" bind:value={to}/><button aria-label={t('Настройка интервала','Configurare interval')} onclick={()=>openInterval({id:kind,current:project.settings.period,from,to,onapply:(a,b)=>{from=a;to=b;}})}>…</button></div>{#each [0,3,4] as i}<ReportFilter language={project.settings.language} label={data.labels[i]} items={data.items[i]} bind:filter={filters[i]}/>{/each}<nav><button disabled={!generated||!ready} onclick={()=>{frame.contentWindow?.focus();frame.contentWindow?.print();}}><Printer size={16}/>{t('Печать','Imprimare')}</button><button disabled={!native||!table} onclick={()=>download('pdf')}><Download size={16}/>{t('Сохранить PDF','Salvează PDF')}</button><button disabled={!table} onclick={()=>download('xlsx')}><Download size={16}/>Excel XLSX</button><button disabled={!table} onclick={()=>download('csv')}><Download size={16}/>CSV</button><button disabled={!table} onclick={()=>download('html')}><Download size={16}/>HTML</button></nav>{#if error}<p role="alert" class="alert error">{error}</p>{/if}{#if generated}<iframe bind:this={frame} title={title} srcdoc={generated} sandbox="allow-same-origin allow-modals" onload={()=>ready=true}></iframe>{/if}</div>
<style>.aux-report{padding:8px;display:flex;flex-direction:column;gap:10px;min-height:100%;box-sizing:border-box}nav,.period{display:flex;gap:8px;align-items:center;flex-wrap:wrap}nav{border-bottom:1px solid var(--border)}nav button,.period button{display:flex;gap:6px;align-items:center;border:0;background:transparent;color:var(--text);padding:8px 10px}.period input{width:170px}iframe{border:0;width:100%;min-height:380px;flex:1;background:white}</style>
